// Simulation state is kept separate so a sensor or SUMO adapter can replace it later.
const initial={floors:[77,74,82,80,76,85,72],queue:42,delay:12};
const defaultPhases=[[1,4,7],[2,5],[3,6]];
let state; const $=id=>document.getElementById(id);
function label(floors){return floors.length?floors.join(', '):'No floors'}
function reset(){state={floors:[...initial.floors],queue:initial.queue,delay:initial.delay,phase:0,enabled:true,updates:0,phases:defaultPhases.map(f=>[...f])};$('phase-error').textContent='';render()}
function render(){const selected=state.phases[state.phase],avg=Math.round(state.floors.reduce((a,b)=>a+b,0)/7);$('occupancy').textContent=avg;$('overall-bar').style.width=avg+'%';$('queue').textContent=state.queue;$('delay').textContent=state.delay;$('mode').setAttribute('aria-pressed',state.enabled);$('mode-label').textContent=state.enabled?'Active':'Inactive';$('advance').disabled=!state.enabled;$('updated').textContent=state.updates?`${state.updates} simulated update${state.updates===1?'':'s'}`:'Initial state';$('phase-count').textContent=`${state.phases.length} PHASES`;
$('floors').innerHTML=state.floors.map((value,i)=>{const floor=i+1,active=state.enabled&&selected.includes(floor),signal=state.enabled?(active?'exit':'wait'):'idle',word=state.enabled?(active?'EXIT':'WAIT'):'OFF';return `<div class="floor-row"><span>Floor ${floor}</span><div class="occupancy-cell"><div class="track"><div class="fill" style="width:${value}%"></div></div><span>${value}%</span></div><button class="signal ${signal}" data-floor="${floor}" aria-label="Floor ${floor}: ${word}. ${state.enabled?'Click to change signal.':'Egress mode inactive.'}" ${state.enabled?'':'disabled'}><b aria-hidden="true">${active?'→':state.enabled?'Ⅱ':'–'}</b>${word}</button></div>`}).reverse().join('');
$('phase-label').innerHTML=state.enabled?`<span class="dot green"></span> PHASE ${state.phase+1} ACTIVE`:'<span class="dot amber"></span> EVENT EGRESS INACTIVE';$('phase-title').textContent=state.enabled?`${label(selected)}${selected.length?' exit':' can exit'}`:'Event egress paused';$('phase-description').textContent=state.enabled?'Click a floor signal to change the active phase':'Enable event egress mode to display phase signals';$('phase-number').innerHTML=`${String(state.phase+1).padStart(2,'0')} <small>/ ${String(state.phases.length).padStart(2,'0')}</small>`;$('steps').innerHTML=state.phases.map((floors,i)=>`<button class="step ${state.enabled&&i===state.phase?'active':''}" data-phase="${i}" aria-pressed="${i===state.phase}"><strong>${i*3}–${i*3+3} min</strong><span>${floors.length?'Floors '+label(floors):'All floors wait'}</span></button>`).join('');const wait=[1,2,3,4,5,6,7].filter(f=>!selected.includes(f));$('sign-go').textContent=state.enabled?(selected.length?`FLOORS ${label(selected)}: EXIT`:'NO FLOORS: EXIT'):'EVENT EGRESS INACTIVE';$('sign-wait').textContent=state.enabled?(wait.length?`FLOORS ${label(wait)}: WAIT`:'NO FLOORS: WAIT'):'NO ACTIVE EXIT INSTRUCTIONS';}
$('floors').addEventListener('click',e=>{const button=e.target.closest('[data-floor]');if(!button||!state.enabled)return;const floor=Number(button.dataset.floor),selected=state.phases[state.phase];state.phases[state.phase]=selected.includes(floor)?selected.filter(f=>f!==floor):[...selected,floor].sort((a,b)=>a-b);render()});
$('steps').addEventListener('click',e=>{const button=e.target.closest('[data-phase]');if(button){state.phase=Number(button.dataset.phase);render()}});
$('floor-choices').innerHTML=Array.from({length:7},(_,i)=>`<label><input type="checkbox" value="${i+1}"> Floor ${i+1}</label>`).join('');
$('add-phase').addEventListener('click',()=>{const floors=Array.from($('floor-choices').querySelectorAll('input:checked'),el=>Number(el.value));if(!floors.length){$('phase-error').textContent='Select at least one floor.';return}state.phases.push(floors);state.phase=state.phases.length-1;$('phase-error').textContent='Phase added.';$('floor-choices').querySelectorAll('input').forEach(el=>el.checked=false);render()});
$('advance').addEventListener('click',()=>{if(!state.enabled)return;state.phases[state.phase].forEach(f=>state.floors[f-1]=Math.max(0,state.floors[f-1]-15));state.queue=Math.max(0,state.queue-4);state.delay=Math.max(0,state.delay-1);state.phase=(state.phase+1)%state.phases.length;state.updates++;render()});$('reset').addEventListener('click',reset);$('mode').addEventListener('click',()=>{state.enabled=!state.enabled;render()});reset();
